function generateId(): string {
  const randomBytes = crypto.getRandomValues(new Uint8Array(6));
  const randomString = Array.from(randomBytes, b => b.toString(16).padStart(2, '0')).join('');
  return `user_${Date.now()}_${randomString}`;
}

